// Synchronous SSI / serial NOR model used by original RP2040 ROM code.
// Models byte transfers and NOR state; analog timing/XIP cache hazards are absent.
export function installROMNOR(rp,size){
 const newer=rp.identifier==='rp2350',ssi=rp.peripherals[0x18000],io=rp.peripherals[newer?0x40030:0x40018],regs=new Map(),ioRegs=new Map(),rx=[];let selected=false,command=-1,address=0,count=0,wel=false,data=[];const stats={erases:0,pages:0};
 function end(){if(wel&&command===2){if(address>=size)throw Error('ROM NOR program kapasite sınırı.');for(let i=0;i<data.length;i++){const at=(address&~255)|((address+i)&255);rp.flash[at]&=data[i];}stats.pages++;wel=false;}if(wel&&[0x20,0x52,0xd8].includes(command)){const n=command===0x20?4096:command===0x52?32768:65536,off=Math.floor(address/n)*n;if(off+n>size)throw Error('ROM NOR erase kapasite sınırı.');rp.flash.fill(255,off,off+n);stats.erases++;wel=false;}command=-1;address=0;count=0;data=[];}
 function transfer(byte){byte&=255;if(!selected)return 255;if(command<0){command=byte;if(byte===6)wel=true;if(byte===4)wel=false;return 0;}count++;if(command===5)return wel?2:0;if(command===0x9f)return[0xef,0x40,Math.log2(size)][(count-1)%3];if([2,3,0x20,0x52,0xd8,0x5a].includes(command)){if(count<=3){address=(address<<8)|byte;return 0;}if(command===3)return rp.flash[(address+count-4)%size];if(command===2){if(data.length>=256)throw Error('ROM NOR page sınırı.');data.push(byte);}return 0;}return 0;}
 io.readUint32=off=>ioRegs.get(off)||0;
 io.writeUint32=(off,value)=>{ioRegs.set(off,value);if(!newer&&off===12){const next=((value>>>8)&3)===2;if(next!==selected){if(!next)end();else{command=-1;address=0;count=0;data=[];}selected=next;}}};
 if(!newer){ssi.readUint32=off=>off===0x20?0:off===0x24?rx.length:off===0x28?6|(rx.length?8:0):off===0x60?(rx.shift()??0):off===0x58?0x51535049:off===0x5c?0x3430312a:regs.get(off)||0;
 ssi.writeUint32=(off,value)=>{if(off===0x60){if(rx.length>=16)throw Error('ROM SSI RX FIFO overflow.');rx.push(transfer(value));}else{regs.set(off,value);if(off===8&&!value)rx.length=0;}};
 }else{const qmi=rp.peripherals[0x400d0],tx=[];let csr=0x1800000;function drain(){if(!(csr&1)||!selected)return;while(tx.length){const v=tx.shift(),wide=!!(v&0x40000);let result=0;result=transfer(v);if(wide)result|=transfer(v>>>8)<<8;if(!(v&0x100000)){if(rx.length>=8)throw Error('ROM QMI RX FIFO overflow.');rx.push(result);}}}qmi.readUint32=off=>off===0?((csr&~0x1f7c02)|(tx.length?tx.length<<12:2048)|(rx.length<<18)|(rx.length===0?65536:0)|(rx.length>=8?131072:0))>>>0:off===8?(rx.shift()??0):regs.get(off)||0;qmi.writeUint32=(off,value)=>{if(off===0){const next=!!(value&4);if(next!==selected){if(!next)end();else{command=-1;address=0;count=0;data=[];}selected=next;}csr=value;drain();}else if(off===4){if(tx.length>=8)throw Error('ROM QMI TX FIFO overflow.');tx.push(value);drain();}else regs.set(off,value);};}return{stats};
}
